from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")
old = """##### 出目52 <怒号の群衆>

- 属性：屋外
- 出現数：1d6+4
- レベル：3
- 戦利品：弾倉2個
- 反応：敵対的
  但し分隊が必ず先制攻撃を行う。
- 崩壊の予感：
  第２ラウンド目開始時、民兵 1d3 名の増援が駆け付ける。
- 激闘の果てに：
  すべての民兵を倒した場合、民兵がため込んでいた物資を発見する。戦利品に加えて戦利品表を１度振る。
"""
new = """##### 出目52 <怒号の群衆>

- 属性：屋外
- 出現数：1d6+4
- レベル：3
- 戦利品：弾倉2個
- 反応：死ぬまで戦う
- 先制：この戦闘ではシナリオ固有効果として、分隊側が必ず先制攻撃を行う。
- 崩壊の予感：
  第1ラウンド終了時点で初期民兵が1名以上生存している場合のみ、第2ラウンド開始時に民兵1d3名の増援が駆け付ける。第1ラウンド中に初期民兵を全滅させた場合、その時点で戦闘は終了し、増援は出現しない。
- 激闘の果てに：
  この戦闘で出現した民兵をすべて倒した場合、民兵がため込んでいた物資を発見する。第1ラウンド中に初期民兵を全滅させて増援を阻止した場合も条件を満たす。戦利品に加えて戦利品表を1度振る。
"""
if s.count(old) != 1:
    raise SystemExit(f"event52 target count must be 1, got {s.count(old)}")
scenario.write_text(s.replace(old, new, 1), encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 21. Black Sun 出目52の撤退・増援・追加戦利品 — 採用済み"
section = """

## 21. Black Sun 出目52の撤退・増援・追加戦利品 — 採用済み

ユーザー承認により、出目52【怒号の群衆】は【死ぬまで戦う】として扱い、シナリオ固有効果として分隊側が必ず先制攻撃を行う。

- 初期民兵は `1d6+4` 名、レベル3、戦利品は弾倉2個のまま変更しない。
- 半数以下による自動撤退は発生しない。
- 第1ラウンド終了時点で初期民兵が1名以上生存している場合のみ、第2ラウンド開始時に `1d3` 名の増援を追加する。
- 第1ラウンド中に初期民兵を全滅させた場合は、その時点で戦闘終了とし、増援は出現しない。
- 第1ラウンド中に初期民兵を全滅させて増援を阻止した場合も「すべての民兵を倒した」とみなし、通常戦利品に加えて戦利品表を1度振る。
- 第2ラウンドに到達した場合は、追加された増援まで全滅させた場合に追加戦利品を得る。

これにより、群衆戦の物量圧力を維持しつつ、高火力・クリティカル連鎖等による早期制圧を増援阻止と追加報酬につなげる。
"""
if heading not in a:
    audit.write_text(a.rstrip() + section + "\n", encoding="utf-8")
